    {
      \"criterion\": \"Inclusivity\",
      \"description\": \"Mechanisms ensure equitable access across varying demographics and baseline protections.\"
    },
    {
      \"criterion\": \"Public Accountability\",
      \"description\": \"Oversight bodies transparently monitor decision-making and implementation impacts.\"
    },
    {
      \"criterion\": \"Temporal Limits\",
      \"description\": \"Differentiation or temporary measures are regularly reviewed and must revert to equality when stability normalizes.\"
